package com.fitnutri.backend.records.food;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.submission.*;
import com.fitnutri.backend.support.*;
import com.fitnutri.backend.user.*;
import java.math.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
class FoodEntryBatchV2IT extends PostgresIntegrationSupport {
 @Autowired FoodEntryV2Service service;@Autowired FoodEntryPreviewService previews;@Autowired FoodRecordRepository records;@Autowired FoodReferenceRepository references;@Autowired FoodDatasetRepository datasets;@Autowired UserRepository users;@Autowired ProfileService profiles;@Autowired UserProfileRepository profileRows;@Autowired SubmissionReceiptRepository receipts;@Autowired FoodSnapshotReader snapshots;@Autowired JdbcTemplate jdbc;@Autowired PlatformTransactionManager manager;
 User owner;FoodReference a,b,c;
 @BeforeEach void setup(){owner=FoodV2TestFixtures.owner(users,profiles);a=FoodV2TestFixtures.reference(datasets,references,"1000");b=FoodV2TestFixtures.reference(datasets,references,"400");c=FoodV2TestFixtures.reference(datasets,references,"500");}
 FoodEntryInputs.Dish dish(){return new FoodEntryInputs.Dish(UUID.randomUUID(),"Synthetic recipe",MealType.DINNER,"FULL_RECIPE",Map.of("kind","FRACTION","numerator",1,"denominator",3),List.of(new FoodEntryInputs.Ingredient(UUID.randomUUID(),a.getId().toString(),new BigDecimal("300"),null,null),new FoodEntryInputs.Ingredient(UUID.randomUUID(),b.getId().toString(),new BigDecimal("150"),null,null)),null);}
 FoodEntryInputs.BatchRequest batch(){var entries=List.<FoodEntryInputs.Entry>of(new FoodEntryInputs.Single(UUID.randomUUID(),c.getId().toString(),new BigDecimal("100"),MealType.LUNCH,null,null),dish());var preview=previews.previewNewBatch(owner.getId(),new FoodEntryInputs.PreviewRequest(LocalDate.of(2020,1,2),"Australia/Sydney",RecordSource.MANUAL,entries));return new FoodEntryInputs.BatchRequest(UUID.randomUUID(),LocalDate.of(2020,1,2),"Australia/Sydney",RecordSource.MANUAL,entries,preview.fingerprint());}
 void empty(UUID submission){assertTrue(records.findByUserIdOrderByRecordedAtDesc(owner.getId()).isEmpty());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM food_dish_record WHERE user_id=?",Long.class,owner.getId()));assertTrue(receipts.findByUserIdAndSubmissionId(owner.getId(),submission).isEmpty());}
 @Test void mixedRootsPersistExactly1700WithPreciseLeavesAndCompleteProof(){var request=batch();var proof=service.createBatchV2(owner.getId(),request);assertFalse(proof.replayed());assertEquals(2,proof.roots().size());assertEquals(3,proof.leaves().size());assertEquals(new BigDecimal("1700.000"),jdbc.queryForObject("SELECT sum(energy_kj) FROM food_record WHERE user_id=?",BigDecimal.class,owner.getId()));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM food_dish_record WHERE user_id=?",Long.class,owner.getId()));var root=proof.roots().stream().filter(r->r.kind().equals("DISH")).findFirst().orElseThrow();var read=snapshots.detailForReuse(owner.getId(),"dish",Long.parseLong(root.id()));assertEquals(new BigDecimal("1200.000"),read.preview().totals().energyKj());assertEquals(List.of(new BigDecimal("100.000000000000"),new BigDecimal("50.000000000000")),read.preview().leaves().stream().map(FoodSnapshotReader.Leaf::consumedGrams).toList());assertTrue(proof.roots().stream().allMatch(r->r.versionAtCreation()==0));assertTrue(proof.leaves().stream().allMatch(r->r.versionAtCreation()==0));}
 @Test void inactiveLaterIngredientRejectsEntireBatchAndLocatesLeaf(){var request=batch();b.setActive(false);references.saveAndFlush(b);var error=assertThrows(BusinessException.class,()->service.createBatchV2(owner.getId(),request));assertEquals("REFERENCE_INACTIVE",error.code());assertEquals(((FoodEntryInputs.Dish)request.entries().get(1)).ingredients().get(1).clientEntryId().toString(),error.fields().getFirst().clientEntryId());empty(request.submissionId());}
 @Test void stalePreviewReturnsCurrentAuthorityWithoutCommitting(){var request=batch();var stale=new FoodEntryInputs.BatchRequest(request.submissionId(),request.recordDate(),request.zone(),request.source(),request.entries(),"0".repeat(64));var error=assertThrows(FoodCalculationChangedV2Exception.class,()->service.createBatchV2(owner.getId(),stale));assertEquals(request.previewFingerprint(),error.currentPreview().fingerprint());empty(request.submissionId());}
 @Test void databaseFailureAfterEarlierInsertRollsBackEveryRootLeafAndReceipt(){var request=batch();String suffix=UUID.randomUUID().toString().replace("-","");String function="test_v2_fail_"+suffix,trigger="test_v2_trigger_"+suffix;jdbc.execute("CREATE FUNCTION "+function+"() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Synthetic late insert rejection' USING ERRCODE='23514'; END$$");jdbc.execute("CREATE TRIGGER "+trigger+" BEFORE INSERT ON food_record FOR EACH ROW WHEN (NEW.user_id="+owner.getId()+" AND NEW.food_reference_id="+b.getId()+") EXECUTE FUNCTION "+function+"()");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->service.createBatchV2(owner.getId(),request));empty(request.submissionId());}finally{jdbc.execute("DROP TRIGGER "+trigger+" ON food_record");jdbc.execute("DROP FUNCTION "+function+"()");}}
 @Test void actualBusinessConcurrentRetriesAndReplayBypassChangedSetupWithoutResurrection()throws Exception{var request=batch();var start=new CountDownLatch(1);SubmissionReceiptV2Response first;try(var pool=Executors.newFixedThreadPool(2)){Callable<SubmissionReceiptV2Response> work=()->{start.await();return service.createBatchV2(owner.getId(),request);};var x=pool.submit(work);var y=pool.submit(work);start.countDown();first=x.get(20,TimeUnit.SECONDS);var second=y.get(20,TimeUnit.SECONDS);assertNotEquals(first.replayed(),second.replayed());assertEquals(first.roots(),second.roots());assertEquals(first.leaves(),second.leaves());}new TransactionTemplate(manager).executeWithoutResult(status->{jdbc.update("UPDATE food_record SET deleted_at=now() WHERE user_id=?",owner.getId());jdbc.update("UPDATE food_dish_record SET deleted_at=now() WHERE user_id=?",owner.getId());});a.setActive(false);references.saveAndFlush(a);var profile=profileRows.findById(owner.getId()).orElseThrow();profile.setAdultConfirmed(false);profileRows.saveAndFlush(profile);var replay=service.createBatchV2(owner.getId(),request);assertTrue(replay.replayed());assertEquals(first.roots(),replay.roots());assertTrue(records.findByUserIdOrderByRecordedAtDesc(owner.getId()).isEmpty());var reused=new FoodEntryInputs.BatchRequest(UUID.randomUUID(),request.recordDate(),request.zone(),request.source(),request.entries(),request.previewFingerprint());assertEquals("CLIENT_ENTRY_CONFLICT",assertThrows(BusinessException.class,()->service.createBatchV2(owner.getId(),reused)).code());}
 @Test void tinyRecipePortionRetainsNonzeroStorageAndNewUuidCreatesIndependentOccurrence(){var entry=new FoodEntryInputs.Dish(UUID.randomUUID(),"Synthetic tiny recipe",MealType.SNACK,"FULL_RECIPE",Map.of("kind","PERCENT","percent",new BigDecimal("0.001")),List.of(new FoodEntryInputs.Ingredient(UUID.randomUUID(),a.getId().toString(),new BigDecimal("0.001"),null,null)),null);var input=new FoodEntryInputs.PreviewRequest(LocalDate.of(2020,1,2),"Australia/Sydney",RecordSource.MANUAL,List.of(entry));var fp=previews.previewNewBatch(owner.getId(),input).fingerprint();var request=new FoodEntryInputs.BatchRequest(UUID.randomUUID(),input.recordDate(),input.zone(),input.source(),input.entries(),fp);var proof=service.createBatchV2(owner.getId(),request);var root=snapshots.detailForReuse(owner.getId(),"dish",Long.parseLong(proof.roots().getFirst().id()));assertEquals(new BigDecimal("0.000000010000"),root.preview().leaves().getFirst().consumedGrams());assertEquals(new BigDecimal("0.000"),root.preview().totals().energyKj());var other=batch();assertFalse(service.createBatchV2(owner.getId(),other).replayed());assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM food_dish_record WHERE user_id=?",Long.class,owner.getId()));}
 @Test void identicalBusinessContentWithFreshRootAndSubmissionIdsIsAnotherOccurrence(){
  var date=LocalDate.of(2020,1,2);var proofs=new java.util.ArrayList<SubmissionReceiptV2Response>();
  for(int i=0;i<2;i++){
   var entry=new FoodEntryInputs.Single(UUID.randomUUID(),c.getId().toString(),new BigDecimal("100"),MealType.LUNCH,null,null);
   var input=new FoodEntryInputs.PreviewRequest(date,"Australia/Sydney",RecordSource.MANUAL,List.of(entry));
   var preview=previews.previewNewBatch(owner.getId(),input);
   proofs.add(service.createBatchV2(owner.getId(),new FoodEntryInputs.BatchRequest(UUID.randomUUID(),date,input.zone(),input.source(),input.entries(),preview.fingerprint())));
  }
  assertTrue(proofs.stream().noneMatch(SubmissionReceiptV2Response::replayed));assertNotEquals(proofs.get(0).submissionId(),proofs.get(1).submissionId());assertNotEquals(proofs.get(0).roots().getFirst().id(),proofs.get(1).roots().getFirst().id());
  assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM food_record WHERE user_id=?",Long.class,owner.getId()));assertEquals(new BigDecimal("1000.000"),jdbc.queryForObject("SELECT sum(energy_kj) FROM food_record WHERE user_id=?",BigDecimal.class,owner.getId()));assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM submission_receipt WHERE user_id=?",Long.class,owner.getId()));
 }

}
